#pragma once

/* The time-zone table (hub_tz.c, generated by tools/time/gen_zones.py). */

#include <stddef.h>

typedef struct {
    const char *name;  /* IANA name, "Europe/Berlin"; sorted, then "UTC" */
    const char *posix; /* its POSIX TZ rule, "CET-1CEST,M3.5.0,M10.5.0/3" */
} hub_tz_t;

extern const hub_tz_t hub_tz[];
extern const size_t hub_tz_count;
